import '../../features/academy/domain/academy_curriculum.dart';

/// Brazilian Portuguese lesson copy keyed by stable curriculum IDs.
class PortugueseAcademyContent {
  PortugueseAcademyContent._();

  static const Map<String, Map<String, Object>> _lessons = {
    'verify_sender': {'title':'Verifique o remetente, não o nome exibido','summary':'Nomes, logotipos e fotos de perfil são fáceis de copiar. Confira o endereço, número ou identificador real da conta antes de confiar em uma solicitação.','keyPoints':['Abra os detalhes do remetente e confira o endereço de e-mail completo ou o identificador da conta.','Diante de uma solicitação inesperada, entre em contato com a pessoa ou organização por um canal que você já sabe ser confiável.','Um nome ou logotipo conhecido não comprova a identidade.'],'question':'Uma mensagem parece vir do seu banco e pede que você aja com urgência. Qual é a primeira atitude mais segura?','options':['Responder e pedir que o remetente confirme','Usar diretamente o aplicativo do banco ou um contato oficial já conhecido','Confiar na mensagem porque o logotipo parece correto'],'explanation':'Use informações de contato obtidas de forma independente. Não confie em links ou telefones fornecidos na mensagem inesperada.'},
    'phishing_links': {'title':'Leia os links antes de abri-los','summary':'Um link pode imitar uma marca confiável e ainda direcionar você para um domínio sem relação ou enganoso.','keyPoints':['Identifique o domínio registrável lendo o nome do host da direita para a esquerda; subdomínios adicionais podem disfarçar o destino.','Desconfie de erros de digitação, caracteres parecidos, encurtadores inesperados e textos de link enganosos.','Em caso de dúvida, use um favorito salvo ou digite você mesmo o endereço conhecido.'],'question':'Uma mensagem mostra “example.com”, mas o link real leva a example-login.security-check.invalid. O que você deve fazer?','options':['Abrir porque o texto visível parece conhecido','Evitar e acessar o serviço pelo canal oficial já conhecido','Abrir em uma janela de navegação privada'],'explanation':'O texto visível de um link pode ser diferente do destino. A navegação privada não torna seguro um destino malicioso.'},
    'otp_secrecy': {'title':'Mantenha OTPs e códigos de recuperação em sigilo','summary':'Senhas de uso único, solicitações de aprovação de login e códigos de recuperação podem permitir que alguém acesse sua conta.','keyPoints':['Nunca informe um OTP ou código de recuperação a quem ligar, a um contato de conversa ou a alguém que se passe pelo suporte.','Não aprove uma solicitação de login que você não iniciou.','Se compartilhou um código, proteja imediatamente a conta pelo serviço oficial.'],'question':'Alguém que afirma trabalhar no suporte pede um OTP para cancelar uma transação. O que você deve fazer?','options':['Informar se a pessoa souber seu nome','Informar apenas a primeira metade','Não informar, encerrar o contato e usar o canal oficial do serviço'],'explanation':'Um OTP é um segredo de autenticação. Um procedimento legítimo de suporte não deve pedir que você o revele.'},
    'mfa_fatigue': {'title':'Reconheça solicitações inesperadas de MFA','summary':'Solicitações de aprovação repetidas ou inesperadas podem indicar que alguém está tentando entrar com suas credenciais.','keyPoints':['Recuse solicitações que você não iniciou.','Não aprove uma solicitação apenas para interromper notificações repetidas.','Se suspeitar de comprometimento, altere a senha pelo serviço oficial e revise as sessões ativas.'],'question':'Seu telefone recebe várias solicitações de aprovação de login quando você não está tentando entrar. Qual é a resposta segura?','options':['Recusar e verificar a conta nas configurações oficiais','Aprovar uma para interromper os alertas','Ignorar todos os alertas futuros da conta'],'explanation':'Recuse solicitações inesperadas. Depois, verifique a conta em um dispositivo confiável e pelo canal oficial.'},
    'payment_pressure': {'title':'Faça uma pausa antes de pagamentos urgentes','summary':'Golpistas usam urgência, segredo e autoridade para pressionar pessoas a fazer transferências, comprar cartões-presente ou aprovar pagamentos.','keyPoints':['Considere de alto risco alterações de última hora em dados bancários e pedidos urgentes de transferência.','Confirme as instruções de pagamento com o destinatário usando um número já conhecido.','Não permita que uma ligação apresse você ou faça ignorar os controles habituais de autorização.'],'question':'Um fornecedor envia novos dados bancários por e-mail e exige pagamento em dez minutos. O que você deve fazer?','options':['Pagar imediatamente para evitar multa','Verificar a alteração usando um contato conhecido anteriormente','Responder ao mesmo e-mail perguntando se é autêntico'],'explanation':'Verifique alterações de pagamento de forma independente. Responder à mesma conversa de e-mail, possivelmente comprometida, não é uma verificação independente.'},
    'qr_safety': {'title':'Trate códigos QR como links','summary':'Um código QR pode conter um site, solicitação de pagamento, ação de contato ou outros dados. Escaneá-lo não o torna confiável.','keyPoints':['Visualize o destino decodificado ou os detalhes do pagamento antes de continuar.','Confira cuidadosamente o beneficiário e o valor antes de autorizar um pagamento.','Desconfie de adesivos QR colocados sobre um código que você esperava encontrar.'],'question':'Um código QR abre uma tela de pagamento. O que você deve verificar antes de aprovar?','options':['Apenas se a imagem do QR parece profissional','O beneficiário, o valor e a finalidade usando uma fonte confiável','Se o código é escaneado rapidamente'],'explanation':'Um código QR é apenas uma forma prática de transportar dados. Confira os detalhes reais da transação antes de autorizá-la.'},
    'device_updates': {'title':'Mantenha dispositivos e aplicativos atualizados','summary':'Atualizações de segurança corrigem vulnerabilidades conhecidas. Adiá-las pode deixar dispositivos expostos a problemas que já têm correção.','keyPoints':['Instale atualizações do sistema e dos aplicativos pelos mecanismos oficiais.','Remova aplicativos que não usa mais e revise as permissões periodicamente.','Mantenha um backup recuperável e proteja o dispositivo com bloqueio de tela.'],'question':'Há uma atualização de aplicativo disponível na loja oficial do dispositivo. Qual é a prática mais segura?','options':['Instalar em tempo hábil após verificar a origem','Baixar de um anúncio qualquer pacote que prometa uma “atualização mais rápida”','Desativar atualizações permanentemente'],'explanation':'Use o mecanismo oficial de atualização da plataforma e mantenha o software razoavelmente atualizado.'},
    'incident_first_steps': {'title':'Aja rapidamente se uma conta puder estar comprometida','summary':'Uma resposta calma e organizada pode limitar novos acessos e preservar informações úteis.','keyPoints':['Em um dispositivo confiável, proteja a conta afetada pelo serviço oficial.','Altere senhas reutilizadas, revogue sessões desconhecidas e ative MFA quando disponível.','Preserve mensagens e registros de transações relevantes; se houver dinheiro envolvido, contate seu banco imediatamente.'],'question':'Você suspeita que sua conta de e-mail foi comprometida. Qual é o melhor ponto de partida?','options':['Excluir imediatamente todas as mensagens suspeitas','Proteger a conta em um dispositivo confiável pelo processo oficial de recuperação','Publicar seus códigos de recuperação na internet para pedir ajuda'],'explanation':'Proteja a conta pelo processo oficial de recuperação, revise as sessões e preserve evidências úteis para a investigação.'},
  };

  static AcademyLesson localize(AcademyLesson lesson, String languageCode) {
    if (languageCode != 'pt') return lesson;
    final values = _lessons[lesson.id];
    if (values == null) return lesson;
    return AcademyLesson(id: lesson.id, title: values['title']! as String, category: lesson.category,
      summary: values['summary']! as String, keyPoints: List<String>.unmodifiable(values['keyPoints']! as List<String>),
      question: values['question']! as String, options: List<String>.unmodifiable(values['options']! as List<String>),
      correctIndex: lesson.correctIndex, explanation: values['explanation']! as String);
  }
}
